blocks.solution:
#include "exercise.h"

void swap(int *a, int *b) {
    int kept = *a;
    *a = *b;
    *b = kept;
}

blocks.tests:
#include <assert.h>
#include <stdio.h>

#include "exercise.h"

int main(void) {
    int a = 1, b = 2;
    swap(&a, &b);
    assert(a == 2 && b == 1);
    int c = -5, d = 9;
    swap(&c, &d);
    assert(c == 9 && d == -5);
    int e = 3;
    swap(&e, &e);
    assert(e == 3);
    puts("3 checks passed");
    return 0;
}
